/** Caller has locked event and current match. A verified PIN permits acceptance only, never account access. */
export async function assertSeasonPinParticipant(client:Client,actor:string,player:string,match:MatchState,options:{existingGrant?:boolean}={}):Promise<void>{
 const link=(await client.query<{entity_id:string;fixture_id:string}>('select l.entity_id,l.fixture_id from dartflow_private.platform_match_links l join dartflow_private.competition_seasons s on s.id=l.entity_id where l.match_id=$1',[match.id])).rows[0];if(!link)throw new DomainError('not_official','Deze partij heeft geen officiële seizoenskoppeling.',409);
 const s=await seasonRow(client,link.entity_id),f=s.fixtures.find(f=>f.slots.some(slot=>slot.id===link.fixture_id&&slot.matchId===match.id)),slot=f?.slots.find(slot=>slot.id===link.fixture_id);
 if(!f||!slot||!['planned','active',...(options.existingGrant?['completed','archived']:[])].includes(s.status)||!['called','ready',...(options.existingGrant?['live','result','confirmed']:[])].includes(match.status)||(!options.existingGrant&&!match.boardId)||match.scoringMode==='per-player'||actor!==match.writerId||!match.players.some(p=>p.id===player)||actor===player||f.status==='disputed'||['administrative','canceled',...(!options.existingGrant?['confirmed']:[])].includes(f.status))throw new DomainError('official_pin_unavailable','Deze toegewezen partij kan nu niet via deze telefoon worden gekoppeld.',409);
 if(!s.rounds.find(r=>r.number===f.round)?.released||!slot.players.includes(player))throw new DomainError('player_ineligible','Deze speler is niet opgesteld voor dit slot.',403);
 if(!await currentSeasonActor(client,s,actor)||(await client.query("select 1 from dartflow_private.platform_registrations where user_id=$1 and status='rejected'",[actor])).rowCount)throw new DomainError('forbidden','Je hebt geen actuele schrijfrechten voor deze vereniging.',403);
 if(s.format==='teams'){const team=s.teams.find(t=>t.playerIds.includes(player));if(!team||team.status!=='active'||!(f.lineups.home?.submittedAt&&f.lineups.away?.submittedAt))throw new DomainError('player_ineligible','Deze speler is niet opgesteld voor dit slot.',403);await eligibleProfile(client,player,team.clubId);}else await eligibleProfile(client,player,s.clubId!);
}
/** The generic scorer must not bypass the current season assignment, published rules or round gate. */
