  const now=Number((await client.query('select extract(epoch from clock_timestamp())*1000 as now')).rows[0].now);if(now<Date.parse(f.windowStart)||now>=Date.parse(f.windowEnd))throw new DomainError('outside_window','Deze officiële partij valt buiten het speelvenster.',409);
